        classes = [[] for _ in range(k)]
        for v in range(n):
            classes[colors[v]].append(v)
        classes.sort(key=len)
        order = []
        for cls in classes:
            # Within class, sort by degree descending
            cls.sort(key=lambda x: -degrees[x])
            order.extend(cls)
        return order

    def reorder_random_class(colors):
        k = count_colors(colors)
        classes = [[] for _ in range(k)]
        for v in range(n):
            classes[colors[v]].append(v)
        random.shuffle(classes)
        order = []
        for cls in classes:
