    if n == 0:
        return []

    # Convert adjacency list to sets for O(1) lookup
    adj_sets = [set(neighbors) for neighbors in adj]

    # Stage 1: Greedy coloring with DSATUR-like ordering
    colors = [-1] * n
    saturation = [0] * n
    degree = [len(adj[i]) for i in range(n)]
    neighbor_colors = [set() for _ in range(n)]

    colored_count = 0
    while colored_count < n:
        # Pick vertex with max saturation, break ties by degree
        best = -1
        best_sat = -1
        best_deg = -1
        for v in range(n):
            if colors[v] == -1:
                if (saturation[v] > best_sat or 
                    (saturation[v] == best_sat and degree[v] > best_deg)):
                    best = v
                    best_sat = saturation[v]
                    best_deg = degree[v]

        v = best
        # Assign smallest available color
        c = 0
        while c in neighbor_colors[v]:
            c += 1
        colors[v] = c

        # Update saturation of neighbors
        for u in adj[v]:
            if colors[u] == -1:
                if c not in neighbor_colors[u]:
                    neighbor_colors[u].add(c)
                    saturation[u] += 1

        colored_count += 1

    # Stage 2: Eliminate rare colors by reassigning vertices
    def get_color_counts():
        counts = {}
        for c in colors:
            counts[c] = counts.get(c, 0) + 1
        return counts

    def try_recolor_vertex(v, forbidden_color):
        """Try to recolor vertex v to avoid forbidden_color or find better color."""
        nc = neighbor_colors[v]
        best_c = -1
        for c in range(max(colors) + 1):
            if c not in nc and c != forbidden_color:
                if best_c == -1 or c < best_c:
                    best_c = c
        return best_c

    # Iteratively try to eliminate the rarest (highest) color
    max_iter = 50
    for _ in range(max_iter):
        num_colors = max(colors) + 1
        if num_colors <= 1:
            break

        counts = get_color_counts()
        # Find the highest color class (rarest among high colors)
        target_color = max(counts.keys())
        target_vertices = [v for v in range(n) if colors[target_color] == target_color 
                          if colors[v] == target_color]

        if not target_vertices:
            break

        # Try to recolor all vertices of target color
        success = True
        recolor_map = {}

        # Temporarily build neighbor colors excluding target color vertices
        for v in target_vertices:
            # Find a color < target_color not used by neighbors
            nc = set()
            for u in adj[v]:
                if u not in target_vertices or u in recolor_map:
                    nc.add(recolor_map.get(u, colors[u]))

            new_c = -1
            for c in range(target_color):
                if c not in nc:
                    new_c = c
                    break

            if new_c == -1:
                success = False
                break
            recolor_map[v] = new_c

        if success:
            # Apply recoloring and update neighbor_colors
            for v, new_c in recolor_map.items():
                old_c = colors[v]
                colors[v] = new_c
                # Update neighbor saturation info
                for u in adj[v]:
                    neighbor_colors[u].discard(old_c)
                    # Check if old_c still present among u's neighbors
                    for w in adj[u]:
                        if colors[w] == old_c:
                            neighbor_colors[u].add(old_c)
                            break
                    neighbor_colors[u].add(new_c)
        else:
            break

    # Normalize colors to be contiguous starting from 0
    color_map = {}
    next_c = 0
    result = []
    for c in colors:
        if c not in color_map:
            color_map[c] = next_c
            next_c += 1
        result.append(color_map[c])

    return result

