    def dsatur_order():
        # DSATUR: order by saturation degree (number of distinct colors in neighborhood)
        colors = [-1] * n
        colored = [False] * n
        saturation = [0] * n
        degree = [len(adj_sets[v]) for v in range(n)]

        order = []
        for _ in range(n):
            # Pick uncolored vertex with max saturation, break ties by degree, then random
            best = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if not colored[v]:
                    if (saturation[v] > best_sat or 
