                        (saturation[v] == best_sat and degree[v] == best_deg and random.random() < 0.3)):
                        best = v
                        best_sat = saturation[v]
                        best_deg = degree[v]

            order.append(best)
            # Assign color
            neighbor_colors = set()
            for u in adj_sets[best]:
                if colors[u] != -1:
                    neighbor_colors.add(colors[u])
            c = 0
            while c in neighbor_colors:
                c += 1
            colors[best] = c
            colored[best] = True

            # Update saturation of neighbors
            for u in adj_sets[best]:
                if not colored[u]:
                    # Recompute saturation for u
                    sat = set()
                    for w in adj_sets[u]:
                        if colors[w] != -1:
                            sat.add(colors[w])
                    saturation[u] = len(sat)

        return colors

    def random_order_color():
        order = list(range(n))
        random.shuffle(order)
        return greedy_color(order)

    def degree_order_color(randomize=False):
        order = list(range(n))
        if randomize:
            # Sort by degree descending with small random perturbation
            order.sort(key=lambda v: -(len(adj_sets[v]) + random.random() * 0.5))
        else:
            order.sort(key=lambda v: -len(adj_sets[v]))
        return greedy_color(order)

    import time
    start = time.time()
    budget = 0.028  # 28ms budget

    best_colors = None
    best_k = n + 1

    # First trial: DSATUR (usually best quality)
    try:
        c = dsatur_order()
        k = count_colors(c)
        if k < best_k:
            best_k = k
            best_colors = c[:]
    except:
        pass

    # Second trial: degree order
    c = degree_order_color(randomize=False)
    k = count_colors(c)
    if k < best_k:
        best_k = k
        best_colors = c[:]

    # Remaining budget: randomized trials
    trial = 0
    while time.time() - start < budget:
        if trial % 3 == 0:
            c = degree_order_color(randomize=True)
        elif trial % 3 == 1:
            c = random_order_color()
        else:
            try:
                c = dsatur_order()
