    return best_colors

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []

    # Welsh-Powell: sort vertices by degree descending
    degrees = [len(adj[v]) for v in range(n)]
    order = sorted(range(n), key=lambda v: -degrees[v])

    colors = [-1] * n

    # First-Fit greedy coloring
    for v in order:
        neighbor_colors = set(colors[u] for u in adj[v] if colors[u] >= 0)
        c = 0
        while c in neighbor_colors:
            c += 1
        colors[v] = c

    def num_colors():
        return max(colors) + 1

    def is_valid():
        for u in range(n):
            for w in adj[u]:
                if colors[u] == colors[w]:
                    return False
        return True

    # Kempe chain interchange to reduce color count
    # Try to eliminate the highest color by recoloring vertices
    def kempe_chain(v, c1, c2):
        # Find the connected component containing v in subgraph induced by colors c1 and c2
        # Then swap c1 and c2 in that component
        stack = [v]
        visited = set()
        component = []
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            if colors[node] == c1 or colors[node] == c2:
                component.append(node)
                for nb in adj[node]:
                    if nb not in visited and (colors[nb] == c1 or colors[nb] == c2):
                        stack.append(nb)
        # Swap colors in component
        for node in component:
            if colors[node] == c1:
                colors[node] = c2
            else:
                colors[node] = c1
        return component

    # Iteratively try to eliminate the highest color class
    max_iterations = min(n * 2, 200)

    for _ in range(max_iterations):
        k = num_colors()
        if k <= 1:
            break

        top_color = k - 1
        # Vertices with the top color
        top_vertices = [v for v in range(n) if colors[v] == top_color]

        if not top_vertices:
            break

        # Try to recolor each vertex in the top color class
        progress = False
        for v in top_vertices:
            if colors[v] != top_color:
                continue

            neighbor_colors = set(colors[u] for u in adj[v] if colors[u] >= 0)

            # Check if we can directly assign a lower color
            for c in range(top_color):
                if c not in neighbor_colors:
                    colors[v] = c
                    progress = True
                    break

            if colors[v] == top_color:
                # Try Kempe chain interchange
                # For each pair of colors (c1, c2) where c1 is a neighbor color and c2 is not
                # Swap Kempe chain of (c1, c2) containing some neighbor to free up c1 for v
                neighbor_col_list = [c for c in neighbor_colors if c < top_color]

                for c1 in neighbor_col_list:
                    # Find a neighbor with color c1
                    nb_c1 = next((u for u in adj[v] if colors[u] == c1), None)
                    if nb_c1 is None:
                        continue

                    # Try swapping c1 with some color not adjacent to v
                    for c2 in range(top_color):
                        if c2 not in neighbor_colors and c2 != c1:
                            # Kempe chain swap on nb_c1 between c1 and c2
                            # Check if v is in this chain (it's not, since v has top_color)
                            old_colors = colors[:]
                            kempe_chain(nb_c1, c1, c2)

                            # Now c1 might be free for v
                            new_neighbor_colors = set(colors[u] for u in adj[v])
                            if c1 not in new_neighbor_colors:
                                colors[v] = c1
                                progress = True
                                break
                            else:
                                # Revert
                                for i in range(n):
                                    colors[i] = old_colors[i]

                    if colors[v] != top_color:
                        break

        # Check if top color is now empty
        if not any(colors[v] == top_color for v in range(n)):
            progress = True

        if not progress:
            break

    # Normalize colors to be contiguous starting from 0
    used = sorted(set(colors))
    remap = {c: i for i, c in enumerate(used)}
    colors = [remap[c] for c in colors]

    return colors

