            used = {colors[v] for v in adj_sets[u] if colors[v] >= 0}
            c = 0
            while c in used:
                c += 1
            colors[u] = c
        return colors

    def count_colors(colors):
        return max(colors) + 1 if colors else 0

    def is_valid(colors):
        for u in range(n):
            for v in adj_sets[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    # DSatur ordering
    def dsatur_order():
        colored = [False] * n
        saturation = [0] * n
        degree = [len(adj_sets[u]) for u in range(n)]
        neighbor_colors = [set() for _ in range(n)]
        colors = [-1] * n
        order = []

        for _ in range(n):
            # Pick vertex with max saturation, break ties by degree
            best = -1
            best_sat = -1
            best_deg = -1
            for u in range(n):
                if not colored[u]:
                    if (saturation[u] > best_sat or 
                        (saturation[u] == best_sat and degree[u] > best_deg)):
                        best = u
                        best_sat = saturation[u]
                        best_deg = degree[u]

            u = best
            used = {colors[v] for v in adj_sets[u] if colors[v] >= 0}
            c = 0
            while c in used:
                c += 1
            colors[u] = c
            colored[u] = True
            order.append(u)

            for v in adj_sets[u]:
                if not colored[v] and c not in neighbor_colors[v]:
                    neighbor_colors[v].add(c)
                    saturation[v] += 1

        return colors

    def try_eliminate_color(colors, target_color):
        """Try to eliminate target_color by recoloring its vertices."""
        num_colors = count_colors(colors)
        vertices_with_target = [u for u in range(n) if colors[u] == target_color]

        colors = colors[:]

        for u in vertices_with_target:
            neighbor_colors = {colors[v] for v in adj_sets[u]}
            # Try to assign a color < target_color
            assigned = False
            for c in range(target_color):
                if c not in neighbor_colors:
                    colors[u] = c
                    assigned = True
                    break

            if not assigned:
                # Try Kempe chain swap
                for c in range(target_color):
                    if c in neighbor_colors:
                        # Find a neighbor with color c and try to swap via Kempe chain
                        for v in adj_sets[u]:
                            if colors[v] == c:
                                # Try swapping colors c and target_color in the component containing v
                                # that uses only colors c and target_color
                                chain = set()
                                stack = [v]
                                while stack:
                                    node = stack.pop()
                                    if node in chain:
                                        continue
                                    chain.add(node)
                                    for w in adj_sets[node]:
                                        if colors[w] in (c, target_color) and w not in chain:
                                            stack.append(w)

                                if u not in chain:
                                    # Swap colors in chain
                                    for node in chain:
                                        colors[node] = c if colors[node] == target_color else target_color
                                    # Now try to color u
                                    nc = {colors[w] for w in adj_sets[u]}
                                    if c not in nc:
                                        colors[u] = c
                                        assigned = True
                                        break
                                    else:
                                        # Undo swap
                                        for node in chain:
                                            colors[node] = c if colors[node] == target_color else target_color
                    if assigned:
                        break

            if not assigned:
                return None  # Failed to eliminate

        # Renumber colors to be contiguous
        mapping = {}
        new_colors = []
        for c in colors:
            if c not in mapping:
                mapping[c] = len(mapping)
            new_colors.append(mapping[c])

        return new_colors

    # Initial coloring with DSatur
    best_colors = dsatur_order()

    # Also try some greedy orderings
    for _ in range(3):
        order = list(range(n))
        random.shuffle(order)
        c = greedy_color(order)
        if count_colors(c) < count_colors(best_colors):
            best_colors = c

    # Squeeze: try to eliminate the highest color class
    improved = True
    while improved:
        improved = False
        num_colors = count_colors(best_colors)
        if num_colors <= 1:
            break

        target = num_colors - 1
        result = try_eliminate_color(best_colors, target)
        if result is not None and count_colors(result) < num_colors:
            best_colors = result
            improved = True

    return best_colors

