                        neighbor_colors[u].add(c)
                        saturation[u] += 1

        return colors

    def num_colors(colors):
        return max(colors) + 1 if colors else 0

    def is_valid(colors):
        for u in range(n):
            for v in adj[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    def kempe_chain_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors

        target = k - 1  # Try to eliminate the last color
        colors = colors[:]

        # Vertices with target color
        target_verts = [v for v in range(n) if colors[v] == target]

        for v in target_verts:
            if colors[v] != target:
                continue
            # Try to recolor v with a color < target using Kempe chain swap
            neighbor_cols = set(colors[u] for u in adj[v])
            # Find two colors not used by v's neighbors to do a Kempe swap
            # Try each pair of colors (c1=target, c2) where c2 < target
            for c2 in range(target):
                if c2 in neighbor_cols:
                    continue
                # c2 is free for v, just recolor directly
                colors[v] = c2
                break
            else:
                # Need Kempe chain swap: pick c1 in neighbor_cols, c2 not in neighbor_cols
                # Find c2 not in neighbor_cols and c2 < target
                free_colors = [c for c in range(target) if c not in neighbor_cols]
                if not free_colors:
                    continue
                c2 = free_colors[0]
                # Find c1 in neighbor_cols, do Kempe chain swap between c1 and c2
                # to free up c2 for v... actually find neighbor using c1
                for c1 in neighbor_cols:
                    if c1 >= target:
                        continue
                    # Kempe chain: swap c1 and c2 in the chain containing a neighbor of v with color c1
                    # This frees c1 for v if c2 wasn't in neighbor_cols
                    # BFS Kempe chain
                    chain = []
                    visited = set()
                    stack = [u for u in adj[v] if colors[u] == c1]
                    for s in stack:
                        if s not in visited:
                            visited.add(s)
                            chain.append(s)
                    i = 0
                    while i < len(chain):
                        node = chain[i]
                        for w in adj[node]:
                            if w not in visited and colors[w] in (c1, c2):
                                visited.add(w)
                                chain.append(w)
                        i += 1
                    # Check if swapping c1<->c2 in chain helps
                    # Swap
                    for node in chain:
                        if colors[node] == c1:
                            colors[node] = c2
                        elif colors[node] == c2:
                            colors[node] = c1
                    # Now try to recolor v
                    new_neighbor_cols = set(colors[u] for u in adj[v])
                    if c1 not in new_neighbor_cols:
                        colors[v] = c1
                        break
                    else:
                        # Undo swap
                        for node in chain:
                            if colors[node] == c1:
                                colors[node] = c2
                            elif colors[node] == c2:
                                colors[node] = c1

        # Check if target color is still used
        if target not in colors:
            return colors
        return colors

    # Run deterministic DSATUR
    best = dsatur(order_seed=None)

    # Run 3 randomized passes
    for seed in [42, 123, 777]:
        candidate = dsatur(order_seed=seed)
        if num_colors(candidate) < num_colors(best):
            best = candidate

    # Apply Kempe chain reduction
    improved = kempe_chain_reduce(best)
    if num_colors(improved) < num_colors(best) and is_valid(improved):
        best = improved
        # Try again
        improved2 = kempe_chain_reduce(best)
        if num_colors(improved2) < num_colors(best) and is_valid(improved2):
            best = improved2

    return best

