        colors = [-1] * n
        saturation = [0] * n
        neighbor_colors = [set() for _ in range(n)]
        degree = [len(adj[v]) for v in range(n)]
        colored = 0
        order = []

        while colored < n:
            best = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colors[v] == -1:
                    if (saturation[v] > best_sat or 
                        (saturation[v] == best_sat and degree[v] > best_deg)):
                        best = v
                        best_sat = saturation[v]
                        best_deg = degree[v]

            used = set()
            for u in adj_sets[best]:
                if colors[u] >= 0:
                    used.add(colors[u])
            c = 0
            while c in used:
