            colors[best] = c
            order.append(best)

            for u in adj_sets[best]:
                if colors[u] == -1:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] += 1
            colored += 1

        return order, colors

