        classes = [[] for _ in range(num_colors)]
        for v in range(n):
            classes[colors[v]].append(v)
        order = []
        for cls in classes:
            order.extend(cls)
        return order

    def order_largest_first():
        return sorted(range(n), key=lambda v: -len(adj[v]))

    def order_random():
        order = list(range(n))
        random.shuffle(order)
        return order

    def order_reverse_color(colors, num_colors):
        classes = [[] for _ in range(num_colors)]
        for v in range(n):
            classes[colors[v]].append(v)
        order = []
        for cls in reversed(classes):
