                if (saturation[v] > best_sat or 
                    (saturation[v] == best_sat and degree[v] > best_deg)):
                    best = v
                    best_sat = saturation[v]
                    best_deg = degree[v]

        v = best
        # Assign smallest available color
        used = neighbor_colors[v]
        c = 0
        while c in used:
            c += 1
        colors[v] = c

        # Update saturation of neighbors
        for u in adj_sets[v]:
            if colors[u] == -1:
                if c not in neighbor_colors[u]:
                    neighbor_colors[u].add(c)
                    saturation[u] += 1

        colored += 1

    # Local improvement: try to eliminate the highest color class
    def get_num_colors():
        return max(colors) + 1

    def try_recolor_class(target_color):
        # Try to recolor all vertices of target_color using other colors
        victims = [v for v in range(n) if colors[v] == target_color]
        new_colors = list(colors)

        for v in victims:
            used = set(new_colors[u] for u in adj_sets[v])
            # Find color != target_color
            c = 0
            while c in used or c == target_color:
                c += 1
            if c < target_color:
                new_colors[v] = c
            else:
                return False, colors  # Can't eliminate
        return True, new_colors

    def kempe_chain_swap(v, c1, c2):
        # Swap colors c1 and c2 in the connected component containing v
        # restricted to vertices colored c1 or c2
        stack = [v]
        visited = {v}
        while stack:
            u = stack.pop()
            if colors[u] == c1:
                colors[u] = c2
            else:
                colors[u] = c1
            for w in adj_sets[u]:
                if w not in visited and colors[w] in (c1, c2):
                    visited.add(w)
                    stack.append(w)

    # Iterative improvement
    max_iter = min(50, n * 2)
    for _ in range(max_iter):
        num_colors = get_num_colors()
        if num_colors <= 1:
            break

        target = num_colors - 1
        success, new_colors = try_recolor_class(target)
        if success:
            colors = new_colors
            continue

        # Try Kempe chain swaps to help recoloring
        victims = [v for v in range(n) if colors[v] == target]
        improved = False
        for v in victims:
            used_colors = set(colors[u] for u in adj_sets[v])
            # Try swapping a neighbor's color with target via Kempe chain
            for u in adj_sets[v]:
                cu = colors[u]
                if cu == target:
