                # Check if swapping cu and target in Kempe chain of u helps v
                # Simulate: after swap, v's neighbor u would have color target
                # Try a different color for u
                other_colors = set(range(num_colors)) - used_colors - {target}
                if other_colors:
                    # Try Kempe chain swap between cu and some other color
                    for oc in other_colors:
