            for u in adj_sets[best]:
                if colors[u] == -1 and c not in nc[u]:
                    nc[u].add(c)
                    saturation[u] += 1
        return colors

    def kempe_chain_swap(colors, v, c1, c2):
        # Swap colors c1 and c2 in the connected component containing v
        # in the subgraph induced by vertices colored c1 or c2
        new_colors = colors[:]
        stack = [v]
        visited = {v}
        while stack:
            u = stack.pop()
            new_colors[u] = c2 if colors[u] == c1 else c1
            for w in adj_sets[u]:
                if w not in visited and (colors[w] == c1 or colors[w] == c2):
                    visited.add(w)
                    stack.append(w)
        return new_colors

