        k = max(colors) + 1
        improved = True
        while improved and k > 1:
            improved = False
            classes = [[] for _ in range(k)]
            for v in range(n):
                classes[colors[v]].append(v)

            # Try to eliminate highest color class
            target = k - 1
            victims = classes[target]
            new_colors = colors[:]
            success = True
            for v in victims:
                used = {new_colors[u] for u in adj_sets[v]}
                c = 0
                while c in used:
                    c += 1
                if c < target:
                    new_colors[v] = c
                else:
                    success = False
