        best = colors[:]
        best_k = max(best) + 1
        current = best[:]

        for it in range(iters):
            k = max(current) + 1
            classes = [[] for _ in range(k)]
            for v in range(n):
                classes[current[v]].append(v)

            r = it % 5
            if r == 0:
                order = [v for cls in classes for v in cls]
            elif r == 1:
                order = [v for cls in reversed(classes) for v in cls]
            elif r == 2:
