                order = list(range(n))
                random.shuffle(order)

            new_c = greedy_color(order)
            new_k = max(new_c) + 1

            if new_k < best_k:
                best_k = new_k
                best = new_c[:]
                current = best[:]
            elif new_k <= best_k + 1:
                current = new_c[:]
            else:
                current = best[:]

        return best

    # Initial coloring with DSatur
    if n <= 5000:
        colors = dsatur_color()
    else:
        order = sorted(range(n), key=lambda v: -degree[v])
