    if n == 0:
        return []

    adj_sets = [set(neighbors) for neighbors in adj]

    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = set()
            for nb in adj_sets[v]:
                if colors[nb] >= 0:
                    used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    def count_colors(colors):
        return max(colors) + 1 if colors else 0

    def is_valid(colors):
        for v in range(n):
            for nb in adj_sets[v]:
                if colors[v] == colors[nb]:
                    return False
        return True

    def order_by_degree_desc():
        return sorted(range(n), key=lambda v: len(adj_sets[v]), reverse=True)

    def order_by_color_class(colors, num_colors):
        # Order: largest color class last (so smallest classes colored first)
        # This is reverse of largest-first for classes
        class_members = [[] for _ in range(num_colors)]
        for v in range(n):
            class_members[colors[v]].append(v)
        # Sort classes by size descending, then within class by degree descending
        class_members.sort(key=lambda cls: len(cls), reverse=True)
        order = []
        for cls in class_members:
            cls.sort(key=lambda v: len(adj_sets[v]), reverse=True)
            order.extend(cls)
        return order

    def order_reverse_color(colors, num_colors):
        # Vertices with higher color assigned first (Culberson style)
        return sorted(range(n), key=lambda v: (-colors[v], -len(adj_sets[v])))

    def order_random_class(colors, num_colors):
        class_members = [[] for _ in range(num_colors)]
        for v in range(n):
            class_members[colors[v]].append(v)
        random.shuffle(class_members)
        order = []
        for cls in class_members:
            random.shuffle(cls)
            order.extend(cls)
        return order

    def kempe_chain_recolor(colors, num_colors):
        # Try to reduce colors by recoloring vertices of the last color
        if num_colors <= 1:
            return colors, num_colors
        colors = colors[:]
        last_color = num_colors - 1
        victims = [v for v in range(n) if colors[v] == last_color]

        for v in victims:
            used = set(colors[nb] for nb in adj_sets[v] if colors[nb] != last_color)
            # Try to assign a color < last_color
            for c in range(last_color):
                if c not in used:
                    colors[v] = c
                    break
            else:
                # Can't reduce, restore
                colors[v] = last_color

        # Check if last_color is still used
        if not any(c == last_color for c in colors):
            return colors, last_color
        return colors, num_colors

    # Initial coloring with degree-descending order
    best_order = order_by_degree_desc()
    best_colors = greedy_color(best_order)
    best_k = count_colors(best_colors)

    # Multi-pass iterated greedy
    max_passes = 50
    no_improve = 0

    for iteration in range(max_passes):
        if no_improve > 15:
            break

        # Choose ordering strategy
        choice = iteration % 4
        if choice == 0:
            order = order_by_color_class(best_colors, best_k)
        elif choice == 1:
            order = order_reverse_color(best_colors, best_k)
        elif choice == 2:
            order = order_random_class(best_colors, best_k)
        else:
            # Degree + random perturbation
            order = order_by_degree_desc()
            # Swap some adjacent pairs
            for _ in range(n // 10 + 1):
                i = random.randint(0, n - 2)
                order[i], order[i+1] = order[i+1], order[i]

        colors = greedy_color(order)
        k = count_colors(colors)

        # Try Kempe chain reduction
        colors, k = kempe_chain_recolor(colors, k)

        if k < best_k:
            best_k = k
            best_colors = colors
            no_improve = 0
        else:
            no_improve += 1

    # Final validation and fix if needed
    if not is_valid(best_colors):
        best_colors = greedy_color(order_by_degree_desc())

    return best_colors

