            v = max(uncolored, key=lambda x: (saturation[x], degree[x]))
            used = colored_neighbors[v]
            c = 0
            while c in used:
                c += 1
            colors[v] = c
            uncolored.remove(v)
            for nb in adj_sets[v]:
                if colors[nb] == -1:
                    if c not in colored_neighbors[nb]:
                        colored_neighbors[nb].add(c)
                        saturation[nb] += 1
        return colors

    def kempe_reduce(colors, k):
        if k <= 1:
            return colors, k
        colors = colors[:]
        changed = True
        while changed and k > 1:
            changed = False
            last = k - 1
            victims = [v for v in range(n) if colors[v] == last]
            for v in victims:
                used = {colors[nb] for nb in adj_sets[v] if colors[nb] != last}
                for c in range(last):
                    if c not in used:
                        colors[v] = c
                        break
            if all(colors[v] != last for v in range(n)):
                k -= 1
                changed = True
        return colors, k

    def recolor_pass(colors, k):
        # Try to move vertices from largest color class to smaller ones
        colors = colors[:]
        class_sizes = [0] * k
        for c in colors:
            class_sizes[c] += 1

        # Try to eliminate the largest-indexed color
        for target in range(k - 1, 0, -1):
