                if colors[nb] == -1 and c not in colored_neighbors[nb]:
                    colored_neighbors[nb].add(c)
                    saturation[nb] += 1
        return colors

    def kempe_reduce(colors, k):
        colors = colors[:]
        changed = True
        while changed and k > 1:
            changed = False
            last = k - 1
            victims = [v for v in range(n) if colors[v] == last]
            all_moved = True
            for v in victims:
                used = {colors[nb] for nb in adj_sets[v] if colors[nb] != last}
                moved = False
                for c in range(last):
                    if c not in used:
                        colors[v] = c
                        moved = True
                        break
                if not moved:
                    all_moved = False
            if all_moved:
                k -= 1
                changed = True
        return colors, k

