        colors = [-1] * n
        for v in order:
            # Find colors used by neighbors
            neighbor_colors = set()
            for u in adj_sets[v]:
                if colors[u] != -1:
                    neighbor_colors.add(colors[u])
            # Assign smallest available color
            c = 0
            while c in neighbor_colors:
                c += 1
            colors[v] = c
        return colors

    def count_colors(colors):
        return max(colors) + 1 if colors else 0

    def dsatur_color(noise=0.0):
        colors = [-1] * n
        saturation = [0] * n
        neighbor_color_sets = [set() for _ in range(n)]
        colored = [False] * n

        for step in range(n):
            # Pick vertex with max saturation, break ties by degree, then random noise
            best = -1
            best_sat = -1
            best_deg = -1
            for v in range(n):
                if colored[v]:
                    continue
                sat = saturation[v]
                deg = degrees[v]
                if noise > 0:
                    # Add small noise to degree for tie-breaking
                    deg_eff = deg + random.uniform(-noise, noise)
                else:
                    deg_eff = deg
                if sat > best_sat or (sat == best_sat and deg_eff > best_deg):
                    best_sat = sat
                    best_deg = deg_eff
                    best = v

            v = best
            # Find smallest available color
            used = neighbor_color_sets[v]
            c = 0
            while c in used:
                c += 1
            colors[v] = c
            colored[v] = True

            # Update saturation of neighbors
            for u in adj_sets[v]:
                if not colored[u]:
                    if c not in neighbor_color_sets[u]:
                        neighbor_color_sets[u].add(c)
                        saturation[u] += 1

        return colors

    def random_order_color():
        order = list(range(n))
        random.shuffle(order)
        return greedy_color(order)

    def largest_first_color(noise=0.0):
        if noise > 0:
            order = sorted(range(n), key=lambda v: degrees[v] + random.uniform(-noise, noise), reverse=True)
        else:
            order = sorted(range(n), key=lambda v: degrees[v], reverse=True)
        return greedy_color(order)

    def is_valid(colors):
        for v in range(n):
            for u in adj_sets[v]:
                if colors[u] == colors[v]:
                    return False
        return True

    import time
    start = time.time()
    budget = 0.028  # 28ms budget

    best_colors = None
    best_k = float('inf')

    # Initial deterministic runs
    for trial_fn, args in [
        (dsatur_color, (0.0,)),
        (largest_first_color, (0.0,)),
    ]:
        colors = trial_fn(*args)
        k = count_colors(colors)
        if k < best_k:
            best_k = k
            best_colors = colors[:]

    # Randomized trials within budget
    trial = 0
    while time.time() - start < budget:
        if trial % 3 == 0:
            colors = dsatur_color(noise=2.0)
        elif trial % 3 == 1:
            colors = largest_first_color(noise=2.0)
        else:
            colors = random_order_color()

        k = count_colors(colors)
        if k < best_k:
            best_k = k
            best_colors = colors[:]
        trial += 1

    # Validate and fix if needed (should not happen)
    if best_colors is None or not is_valid(best_colors):
        best_colors = dsatur_color(0.0)

    return best_colors

