    n = len(adj)
    if n == 0:
        return []

    # Welsh-Powell: sort vertices by degree descending
    degrees = [len(adj[v]) for v in range(n)]
    order = sorted(range(n), key=lambda v: -degrees[v])

    colors = [-1] * n

    # First-Fit greedy coloring
    for v in order:
        neighbor_colors = set(colors[u] for u in adj[v] if colors[u] >= 0)
        c = 0
        while c in neighbor_colors:
            c += 1
        colors[v] = c

    num_colors = max(colors) + 1

    def is_valid():
        for u in range(n):
            for v in adj[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    def try_kempe_chain_reduction():
        nonlocal num_colors
        # Try to eliminate the highest color by Kempe chain interchanges
        max_color = num_colors - 1
        max_class = [v for v in range(n) if colors[v] == max_color]

        if not max_class:
            return False

        improved = False
        for v in max_class:
            if colors[v] != max_color:
                continue
            # Try to recolor v using a Kempe chain interchange with each lower color
            neighbor_cols = set(colors[u] for u in adj[v])
            # Find a color not used by neighbors (shouldn't be max_color then)
            for target_color in range(max_color):
                if target_color not in neighbor_cols:
                    colors[v] = target_color
                    improved = True
                    break

            if colors[v] == max_color:
                # Try Kempe chain: pick a neighbor color and swap chain
                for alt_color in range(max_color):
                    if alt_color in neighbor_cols:
                        # Find another color not in neighbor_cols to swap with
                        for swap_color in range(max_color):
                            if swap_color != alt_color and swap_color not in neighbor_cols:
                                # Do Kempe chain interchange between alt_color and swap_color
                                # starting from v's perspective: swap colors in the chain
                                # containing alt_color neighbors of v
                                chain = []
                                visited = set()
                                stack = [u for u in adj[v] if colors[u] == alt_color]
                                for s in stack:
                                    visited.add(s)
                                    chain.append(s)

                                idx = 0
                                while idx < len(chain):
                                    node = chain[idx]
                                    idx += 1
                                    for w in adj[node]:
                                        if w not in visited and colors[w] in (alt_color, swap_color):
                                            visited.add(w)
                                            chain.append(w)

                                # Swap colors in chain
                                for node in chain:
                                    if colors[node] == alt_color:
                                        colors[node] = swap_color
                                    else:
                                        colors[node] = alt_color

                                # Check if v can now be recolored
                                neighbor_cols2 = set(colors[u] for u in adj[v])
                                if max_color not in neighbor_cols2 or True:
                                    if swap_color not in neighbor_cols2:
                                        colors[v] = swap_color
                                        improved = True
                                        break
                                    elif alt_color not in neighbor_cols2:
                                        colors[v] = alt_color
                                        improved = True
                                        break

                                if colors[v] != max_color:
                                    break

                                # Revert chain swap if didn't help
                                if colors[v] == max_color:
                                    for node in chain:
                                        if colors[node] == alt_color:
                                            colors[node] = swap_color
                                        else:
                                            colors[node] = alt_color

                        if colors[v] != max_color:
                            break

        # Check if max_color class is now empty
        remaining = [v for v in range(n) if colors[v] == max_color]
        if not remaining:
            num_colors = max_color
            return True
        return improved

    # Iteratively try to reduce colors
    max_iter = num_colors * 2
    for _ in range(max_iter):
        if num_colors <= 1:
            break
        changed = try_kempe_chain_reduction()
        # Recompute num_colors
        actual_max = max(colors) + 1
        if actual_max < num_colors:
            num_colors = actual_max
        if not changed:
            break

    # Normalize colors to be contiguous from 0
    used = sorted(set(colors))
    remap = {c: i for i, c in enumerate(used)}
    colors = [remap[c] for c in colors]

    return colors

