        k = num_colors(colors)
        target = k - 1
        # Vertices with the target color
        target_verts = [u for u in range(n) if colors[u] == target]

        new_colors = colors[:]
        for u in target_verts:
            used = {new_colors[v] for v in neighbors[u]}
            # Try to recolor u with an existing color < target
