                            chain.add(v)
                            for w in neighbors[v]:
                                if w not in chain and new_colors[w] in (bc, c):
                                    stack.append(w)
                        # Check if u is not in chain (it shouldn't be)
                        if u not in chain:
                            # Swap bc and c in chain
                            for v in chain:
                                new_colors[v] = c if new_colors[v] == bc else bc
                            # Now try to color u
                            used2 = {new_colors[v] for v in neighbors[u]}
