            excluded = set()
            ind_set = []
            # Start with highest degree in uncolored
            v = max(candidates, key=lambda x: len(adj_sets[x] & uncolored))
            while candidates:
                ind_set.append(v)
                new_excluded = adj_sets[v] & candidates
                candidates -= new_excluded
                candidates.discard(v)
                excluded |= new_excluded
                if candidates:
                    # Pick vertex in candidates with most neighbors in excluded
                    v = max(candidates, key=lambda x: len(adj_sets[x] & excluded))
            for v in ind_set:
                colors[v] = color
                uncolored.discard(v)
            color += 1
