            if success:
                # Renumber colors
                mapping = {}
                new_c = 0
                new_colors = [0] * n
                for v in range(n):
                    if colors[v] not in mapping:
                        mapping[colors[v]] = new_c
                        new_c += 1
                    new_colors[v] = mapping[colors[v]]
