        stack = [v]
        visited = set()
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if colors[u] == c1:
                colors[u] = c2
            elif colors[u] == c2:
                colors[u] = c1
            else:
