    def kempe_chain_swap(colors, v, c1, c2):
        # Swap colors c1 and c2 in the Kempe chain containing v
        col = colors[:]
        stack = [v]
        visited = {v}
        while stack:
            u = stack.pop()
            old = col[u]
            col[u] = c2 if old == c1 else c1
            for w in adj[u]:
                if w not in visited and col[w] in (c1, c2):
                    visited.add(w)
                    stack.append(w)
        return col

