            best = max(uncolored, key=lambda v: (sat[v], deg[v]))
            uncolored.remove(best)
            used = {colors[u] for u in adj[best] if colors[u] >= 0}
            c = 0
            while c in used: c += 1
            colors[best] = c
            for u in adj[best]:
                if u in uncolored and c not in nc[u]:
                    nc[u].add(c)
                    sat[u] += 1
        return colors

    def greedy_recolor(colors):
        col = colors[:]
        # Multiple passes, reassigning to smallest feasible color
        for _ in range(3):
            changed = False
            order = sorted(range(n), key=lambda v: -col[v])
            for v in order:
                used = {col[u] for u in adj[v]}
                best_c = col[v]
                for c in range(col[v]):
                    if c not in used:
                        best_c = c
                        break
                if best_c != col[v]:
                    col[v] = best_c
                    changed = True
            if not changed:
                break
        return col

    def try_eliminate(colors, target):
        col = colors[:]
        k = max(col) + 1
        victims = [v for v in range(n) if col[v] == target]
        victims.sort(key=lambda v: len(adj[v]), reverse=True)
        for v in victims:
            used = {col[u] for u in adj[v]}
            # Direct assignment
            assigned = False
            for c in range(k):
                if c != target and c not in used:
                    col[v] = c
                    assigned = True
                    break
            if assigned:
                continue
            # Try Kempe chain swaps
            for c_block in list(used):
                if c_block == target:
                    continue
                # Try to swap c_block with target in chain from neighbor
                for u in adj[v]:
                    if col[u] != c_block:
                        continue
                    # BFS chain of colors c_block and target from u
                    chain = set()
                    stack = [u]
                    chain.add(u)
                    while stack:
                        w = stack.pop()
                        for x in adj[w]:
                            if x not in chain and col[x] in (c_block, target):
                                chain.add(x)
                                stack.append(x)
                    if v not in chain:
                        for w in chain:
                            col[w] = target if col[w] == c_block else c_block
                        used = {col[u2] for u2 in adj[v]}
                        for c2 in range(k):
                            if c2 != target and c2 not in used:
                                col[v] = c2
                                assigned = True
                                break
                        if assigned:
                            break
                if assigned:
                    break
            if not assigned:
                return None
