    best = greedy_recolor(dsatur())
    best_k = max(best) + 1

    # Also try degree-ordered greedy
    order2 = sorted(range(n), key=lambda v: -len(adj[v]))
    tmp = [-1] * n
    for v in order2:
        used = {tmp[u] for u in adj[v] if tmp[u] >= 0}
        c = 0
        while c in used: c += 1
        tmp[v] = c
    tmp = greedy_recolor(tmp)
    if max(tmp) + 1 < best_k:
        best = tmp
        best_k = max(best) + 1

    current = best[:]
    rng = random.Random(42)

    for iteration in range(20):
        k = max(current) + 1
        # Try eliminate highest color
        result = try_eliminate(current, k - 1)
        if result is not None:
            current = greedy_recolor(result)
            ck = max(current) + 1
            if ck < best_k:
                best_k = ck
                best = current[:]
        else:
            # Perturbation: random reorder by color class size
            classes = [[] for _ in range(k)]
            for v in range(n):
                classes[current[v]].append(v)
            classes.sort(key=len, reverse=True)
            if iteration % 3 == 0:
                rng.shuffle(classes)
            order = [v for cls in classes for v in cls]
            tmp = [-1] * n
            for v in order:
                used = {tmp[u] for u in adj[v] if tmp[u] >= 0}
                c = 0
                while c in used: c += 1
                tmp[v] = c
            current = greedy_recolor(tmp)
            ck = max(current) + 1
            if ck < best_k:
                best_k = ck
                best = current[:]
            elif ck > best_k + 2:
                current = best[:]

    return best

