            for u in adj[best]:
                if u in uncolored and c not in neighbor_colors[u]:
                    neighbor_colors[u].add(c)
                    sat[u] += 1
        return colors

    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = {colors[u] for u in adj[v] if colors[u] >= 0}
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    def recolor_pass(colors):
        col = colors[:]
        order = sorted(range(n), key=lambda v: -col[v])
        for v in order:
            used = {col[u] for u in adj[v]}
            for c in range(col[v]):
                if c not in used:
                    col[v] = c
                    break
        return col

    def try_eliminate_color(colors, target_c):
        col = colors[:]
        num_c = max(col) + 1
        victims = [v for v in range(n) if col[v] == target_c]
        victims.sort(key=lambda v: len(adj[v]), reverse=True)
        for v in victims:
            used = {col[u] for u in adj[v]}
            assigned = False
            for c in range(num_c):
                if c != target_c and c not in used:
                    col[v] = c
                    assigned = True
                    break
            if not assigned:
                freed = False
                for c in range(num_c):
                    if c == target_c or c not in used:
                        continue
                    for u in adj[v]:
                        if col[u] == c:
                            chain = set()
                            stack = [u]
                            chain.add(u)
