    colors = [-1] * n
    saturation = [0] * n  # number of distinct colors in neighborhood
    degree = [len(adj[i]) for i in range(n)]
    neighbor_colors = [set() for _ in range(n)]

    # Use a simple greedy DSATUR
    colored = 0
    while colored < n:
        # Pick uncolored vertex with max saturation, break ties by degree
        best = -1
        best_sat = -1
        best_deg = -1
        for v in range(n):
            if colors[v] == -1:
                if (saturation[v] > best_sat or 
                    (saturation[v] == best_sat and degree[v] > best_deg)):
                    best = v
                    best_sat = saturation[v]
                    best_deg = degree[v]

        v = best
        # Assign smallest available color
        used = neighbor_colors[v]
        c = 0
        while c in used:
            c += 1
        colors[v] = c
        colored += 1

        # Update saturation of neighbors
        for u in adj[v]:
            if colors[u] == -1 and c not in neighbor_colors[u]:
                neighbor_colors[u].add(c)
                saturation[u] += 1

    num_colors = max(colors) + 1

    # Local improvement: try to eliminate the highest color class
    def try_reduce():
        nonlocal num_colors, colors
        max_c = num_colors - 1
        # Get vertices with the max color
        max_class = [v for v in range(n) if colors[v] == max_c]

        for v in max_class:
            # Try to recolor v with a color < max_c
            used = {colors[u] for u in adj[v]}
            alt = None
            for c in range(max_c):
                if c not in used:
                    alt = c
                    break
            if alt is not None:
                colors[v] = alt

        # Check if max color class is now empty
        if not any(colors[v] == max_c for v in range(n)):
            num_colors -= 1
            return True
        return False

    # Kempe chain swap: try to free a color slot for a vertex
    def kempe_chain_recolor(v, c1, c2):
        # Swap colors c1 and c2 in the connected component containing v
        # in the subgraph induced by vertices colored c1 or c2
        stack = [v]
        visited = set()
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            old = colors[u]
            colors[u] = c2 if old == c1 else c1
            for w in adj[u]:
                if w not in visited and colors[w] in (c1, c2):
                    stack.append(w)

