    def kempe_improve():
        nonlocal num_colors, colors
        max_c = num_colors - 1
        max_class = [v for v in range(n) if colors[v] == max_c]

        for v in max_class:
            used = {colors[u] for u in adj[v]}
            if max_c not in used:
                continue
            # Try Kempe chain with each alternative color
            for c in range(max_c):
                if c not in used:
                    colors[v] = c
