                for c in range(max_c):
                    if c in used:
                        # Find a color not used by v's neighbors
                        for c2 in range(max_c):
                            if c2 not in used and c2 != c:
                                # Save state
                                old_colors = colors[:]
                                kempe_chain_recolor(
                                    next(u for u in adj[v] if colors[u] == c),
                                    c, c2
