        """Try to recolor v with a color < target_max_color"""
        used = set(colors[u] for u in adj[v])
        for c in range(target_max_color):
            if c not in used:
                colors[v] = c
                return True
        return False

    def kempe_chain_swap(v, c1, c2):
        """Swap colors c1 and c2 in the Kempe chain containing v"""
        # BFS/DFS through vertices colored c1 or c2 connected to v
        stack = [v]
        visited = {v}
