    if n == 1:
        return [0]

    adj_sets = [set(neighbors) for neighbors in adj]
    degrees = [len(adj_sets[v]) for v in range(n)]

    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = {colors[u] for u in adj_sets[v] if colors[u] >= 0}
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    def dsatur_color():
        colors = [-1] * n
        saturation = [0] * n
        neighbor_colors = [set() for _ in range(n)]
        colored = 0
        # Use a simple selection each step
        uncolored = set(range(n))
        while uncolored:
            # Pick vertex with max saturation, break ties by degree
            v = max(uncolored, key=lambda x: (saturation[x], degrees[x]))
            uncolored.remove(v)
            used = neighbor_colors[v]
            c = 0
            while c in used:
                c += 1
            colors[v] = c
            for u in adj_sets[v]:
                if colors[u] < 0:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] += 1
        return colors

    def count_colors(colors):
        return max(colors) + 1

    def is_valid(colors):
        for v in range(n):
            for u in adj_sets[v]:
                if colors[v] == colors[u]:
                    return False
        return True

    def get_order_by_classes(colors, k, reverse=False, shuffle=False):
        classes = [[] for _ in range(k)]
        for v in range(n):
            classes[colors[v]].append(v)
        if shuffle:
            random.shuffle(classes)
            for cls in classes:
                random.shuffle(cls)
        else:
            classes.sort(key=lambda cls: len(cls), reverse=not reverse)
            for cls in classes:
                cls.sort(key=lambda v: -degrees[v])
        result = []
        for cls in classes:
            result.extend(cls)
        return result

    # Start with DSatur
    best_colors = dsatur_color()
    best_k = count_colors(best_colors)

    if best_k <= 2:
        return best_colors

    # Also try degree-ordered greedy
    order = sorted(range(n), key=lambda v: -degrees[v])
    c2 = greedy_color(order)
    k2 = count_colors(c2)
