        iteration += 1

        if no_improve >= 30:
            current_colors = best_colors[:]
            current_k = best_k
            no_improve = 0

        r = iteration % 5
        if r == 0:
            new_order = get_order_by_classes(current_colors, current_k, reverse=False)
        elif r == 1:
            new_order = get_order_by_classes(current_colors, current_k, reverse=True)
        elif r == 2:
            new_order = get_order_by_classes(current_colors, current_k, shuffle=True)
        elif r == 3:
            new_order = list(range(n))
            random.shuffle(new_order)
        else:
            # Degree + random perturbation
            new_order = sorted(range(n), key=lambda v: (-degrees[v], random.random()))

        new_colors = greedy_color(new_order)
        new_k = count_colors(new_colors)

        if new_k < best_k:
            best_colors = new_colors[:]
            best_k = new_k
            current_colors = new_colors[:]
            current_k = new_k
            no_improve = 0
        elif new_k <= current_k:
            current_colors = new_colors[:]
            current_k = new_k
            no_improve += 1
        else:
            no_improve += 1

    if not is_valid(best_colors):
        order = sorted(range(n), key=lambda v: -degrees[v])
        best_colors = greedy_color(order)

    return best_colors

