    # Convert adjacency list to sets for O(1) lookup
    adj_sets = [set(neighbors) for neighbors in adj]

    def greedy_color(order):
        colors = [-1] * n
        for u in order:
            used = {colors[v] for v in adj_sets[u] if colors[v] >= 0}
            c = 0
            while c in used:
                c += 1
            colors[u] = c
        return colors

    def count_colors(colors):
        return max(colors) + 1 if colors else 0

    def is_valid(colors):
        for u in range(n):
            for v in adj_sets[u]:
                if colors[u] == colors[v]:
                    return False
        return True

    # DSATUR-like ordering: sort by degree descending, then saturation
    def dsatur_order():
        colors = [-1] * n
        saturation = [0] * n
        degree = [len(adj_sets[u]) for u in range(n)]
        colored = [False] * n
        order = []

        for _ in range(n):
            # Pick uncolored vertex with max saturation, break ties by degree
            best = -1
            for u in range(n):
                if not colored[u]:
                    if best == -1:
                        best = u
                    elif (saturation[u], degree[u]) > (saturation[best], degree[best]):
                        best = u

            order.append(best)
            colored[best] = True

            # Assign color greedily
            used = {colors[v] for v in adj_sets[best] if colors[v] >= 0}
            c = 0
            while c in used:
                c += 1
            colors[best] = c

            # Update saturation of neighbors
            for v in adj_sets[best]:
                if not colored[v]:
                    neighbor_colors = {colors[w] for w in adj_sets[v] if colors[w] >= 0}
                    saturation[v] = len(neighbor_colors)

        return colors

    def try_eliminate_color(colors, target_color):
        """Try to eliminate target_color by recoloring its vertices."""
        num_colors = count_colors(colors)
        colors = colors[:]
        vertices_with_target = [u for u in range(n) if colors[u] == target_color]

        for u in vertices_with_target:
            neighbor_colors = {colors[v] for v in adj_sets[u]}
            # Try to assign a different color (not target_color, not neighbor colors)
            assigned = False
            for c in range(num_colors - 1):
                if c != target_color and c not in neighbor_colors:
                    colors[u] = c
                    assigned = True
                    break

            if not assigned:
                # Try Kempe chain swap: pick a neighbor's color and swap chains
                for c in range(num_colors - 1):
                    if c != target_color and c not in neighbor_colors:
                        colors[u] = c
                        assigned = True
                        break

                if not assigned:
                    # Try recoloring neighbors to free up a color
                    for v in adj_sets[u]:
                        if colors[v] == target_color:
                            continue
                        old_c = colors[v]
                        v_neighbor_colors = {colors[w] for w in adj_sets[v] if w != u}
                        for c in range(num_colors - 1):
                            if c != old_c and c not in v_neighbor_colors:
                                colors[v] = c
                                # Now try u again
                                u_neighbor_colors = {colors[w] for w in adj_sets[u]}
                                if target_color not in u_neighbor_colors:
                                    pass  # u still has target, that's fine if we reassign
                                for cu in range(num_colors - 1):
                                    if cu != target_color and cu not in u_neighbor_colors:
                                        colors[u] = cu
                                        assigned = True
                                        break
                                if assigned:
                                    break
                                colors[v] = old_c  # revert
                        if assigned:
                            break

                    if not assigned:
                        return None  # Failed to eliminate

        # Remap colors to be contiguous
        if target_color in colors:
            return None

        # Remap: remove target_color gap
        mapping = {}
        new_c = 0
        for c in range(num_colors):
            if c != target_color:
                mapping[c] = new_c
                new_c += 1
        return [mapping[c] for c in colors]

    # Initial coloring with DSATUR
    best_colors = dsatur_order()

    # Also try degree-sorted greedy
    degree_order = sorted(range(n), key=lambda u: -len(adj_sets[u]))
    greedy_colors = greedy_color(degree_order)
    if count_colors(greedy_colors) < count_colors(best_colors):
        best_colors = greedy_colors

    # Squeeze: try to eliminate the highest color
    improved = True
    while improved:
        improved = False
        num_colors = count_colors(best_colors)
        if num_colors <= 1:
            break
        target = num_colors - 1
        result = try_eliminate_color(best_colors, target)
        if result is not None and is_valid(result):
            best_colors = result
            improved = True

    return best_colors

