        target_verts = [v for v in range(n) if colors[v] == target]
        if not target_verts:
            return colors

        # Try to recolor each target vertex using Kempe chain swaps
        for v in target_verts:
            if colors[v] != target:
                continue  # already recolored

            # Try each color c < target
            neighbor_cols = set(colors[nb] for nb in adj[v])

            for c in range(target):
                if c in neighbor_cols:
                    continue
                # Can directly recolor
                colors[v] = c
                break
            else:
                # Try Kempe chain: for each color c not used by neighbors of v
                # find a color d used by neighbors, do Kempe chain swap on (c,d) subgraph
                # to free color c at v
                for c in range(target):
                    if c in neighbor_cols:
                        continue
                    # c is free at v - already handled above
                    break
                else:
                    # All colors 0..target-1 are used by neighbors
                    # Try Kempe chain between two neighbor colors to free one
                    nb_col_list = list(neighbor_cols - {target})
                    if len(nb_col_list) < 2:
                        continue

                    # Try swapping Kempe chain (c1, c2) starting from a neighbor
                    for i in range(min(len(nb_col_list), 4)):
                        c1 = nb_col_list[i]
                        for j in range(i+1, min(len(nb_col_list), 4)):
