                            # BFS Kempe chain on colors c1,c2 from start
                            chain = []
                            visited = set()
                            queue = [start]
                            visited.add(start)
                            while queue:
                                u = queue.pop()
                                chain.append(u)
                                for nb2 in adj[u]:
                                    if nb2 not in visited and colors[nb2] in (c1, c2):
                                        visited.add(nb2)
                                        queue.append(nb2)

                            # Check if swapping this chain frees c1 at v
                            # After swap: c1->c2, c2->c1 in chain
                            # v's neighbor with c1 becomes c2
                            # Check if any neighbor of v in chain still has c1
                            v_neighbors_in_chain = set(adj[v]) & visited
                            all_become_c2 = all(colors[nb2] == c1 for nb2 in v_neighbors_in_chain)

                            if all_become_c2:
                                # Swap
                                for u in chain:
                                    colors[u] = c2 if colors[u] == c1 else c1
                                colors[v] = c1
                                break
                        else:
