        for v in order:
            used = {colors[u] for u in adj_sets[v] if colors[u] >= 0}
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    def dsatur_order(randomized=False):
        degrees = [len(a) for a in adj]
        colors = [-1] * n
        saturation = [0] * n
        neighbor_colors = [set() for _ in range(n)]
        colored = 0
        order = []
        uncolored = set(range(n))

        while colored < n:
            if randomized:
                max_sat = max(saturation[v] for v in uncolored)
                candidates = [v for v in uncolored if saturation[v] == max_sat]
                if len(candidates) > 1:
                    max_deg = max(degrees[v] for v in candidates)
                    candidates = [v for v in candidates if degrees[v] == max_deg]
                v = random.choice(candidates)
            else:
                v = max(uncolored, key=lambda x: (saturation[x], degrees[x]))

            used = {colors[u] for u in adj_sets[v] if colors[u] >= 0}
            c = 0
            while c in used:
                c += 1
            colors[v] = c
            order.append(v)
            uncolored.remove(v)
            colored += 1

            for u in adj_sets[v]:
                if colors[u] == -1:
                    if c not in neighbor_colors[u]:
                        neighbor_colors[u].add(c)
                        saturation[u] += 1
        return colors

    def rlf_color():
        colors = [-1] * n
        current_color = 0
        uncolored = set(range(n))

        while uncolored:
            # Build independent set
            candidates = set(uncolored)
            # Start with highest degree in uncolored subgraph
            v = max(candidates, key=lambda x: sum(1 for nb in adj_sets[x] if nb in candidates))
            ind_set = {v}
            candidates -= adj_sets[v]
            candidates.discard(v)

            while candidates:
                # Pick vertex with most neighbors in uncolored but not in candidates (already excluded)
                best = max(candidates, key=lambda x: (
                    sum(1 for nb in adj_sets[x] if nb in uncolored and nb not in ind_set),
                    -sum(1 for nb in adj_sets[x] if nb in candidates)
                ))
                ind_set.add(best)
                candidates -= adj_sets[best]
                candidates.discard(best)

            for v in ind_set:
                colors[v] = current_color
                uncolored.discard(v)
            current_color += 1

        return colors

    def kempe_reduce(colors):
        colors = colors[:]
        num_colors = max(colors) + 1

        for target in range(num_colors - 1, 0, -1):
            # Try to eliminate color 'target' by kempe chain swaps
            verts_with_target = [v for v in range(n) if colors[v] == target]
            if not verts_with_target:
                continue

            for v in verts_with_target:
                if colors[v] != target:
                    continue
                # Try swapping with each lower color
                for alt in range(target):
                    if any(colors[u] == alt for u in adj_sets[v]):
                        continue
                    colors[v] = alt
                    break

            # Renumber if target color is gone
            if not any(c == target for c in colors):
                num_colors -= 1

        return colors

    def validate_and_fix(colors):
        colors = colors[:]
        for v in range(n):
            used = {colors[u] for u in adj_sets[v] if u != v}
            if colors[v] in used:
                c = 0
                while c in used:
                    c += 1
                colors[v] = c
        return colors

    best = None

    # RLF
    c1 = rlf_color()
    c1 = validate_and_fix(c1)
    best = c1

    # DSATUR deterministic
    c2 = dsatur_order(randomized=False)
    c2 = validate_and_fix(c2)
    if max(c2) < max(best):
        best = c2

    # Randomized DSATUR runs
    for _ in range(5):
        c = dsatur_order(randomized=True)
        c = validate_and_fix(c)
        if max(c) < max(best):
            best = c

    # Kempe chain reduction
    best = kempe_reduce(best)
    best = validate_and_fix(best)

    return best

