def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []

    # Convert adjacency list to sets for O(1) lookup
    adj_sets = [set(neighbors) for neighbors in adj]

    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = set()
            for u in adj_sets[v]:
                if colors[u] >= 0:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    def count_colors(colors):
        return max(colors) + 1 if colors else 0

    def get_color_classes(colors, num_colors):
        classes = [[] for _ in range(num_colors)]
        for v, c in enumerate(colors):
            classes[c].append(v)
        return classes

    def order_by_color_classes(colors, num_colors):
        # Reverse color class order: largest class last (DSatur-like reordering)
        classes = get_color_classes(colors, num_colors)
        # Sort classes by size descending, then flatten
        classes.sort(key=lambda cls: -len(cls))
        order = []
        for cls in classes:
            order.extend(cls)
        return order

    def order_by_degree_desc():
        return sorted(range(n), key=lambda v: -len(adj_sets[v]))

    def order_random():
        order = list(range(n))
        random.shuffle(order)
        return order

    def order_by_saturation(colors):
        # DSATUR-style: order by saturation degree (number of distinct neighbor colors)
        sat = [0] * n
        for v in range(n):
            neighbor_colors = set()
            for u in adj_sets[v]:
                if colors[u] >= 0:
                    neighbor_colors.add(colors[u])
            sat[v] = len(neighbor_colors)
        return sorted(range(n), key=lambda v: (-sat[v], -len(adj_sets[v])))

    def try_reduce_colors(colors, num_colors):
        # Try to eliminate the largest color class by recoloring its vertices
        classes = get_color_classes(colors, num_colors)
        # Find smallest color class to eliminate
        smallest_class = min(classes, key=len)
        new_colors = colors[:]
        success = True
        for v in smallest_class:
            used = set()
            for u in adj_sets[v]:
                used.add(new_colors[u])
            # Try to assign a color < num_colors - 1
            assigned = False
            for c in range(num_colors - 1):
                if c not in used:
                    new_colors[v] = c
                    assigned = True
                    break
            if not assigned:
                success = False
                break
        if success:
            # Renormalize colors
            mapping = {}
            result = []
            for c in new_colors:
                if c not in mapping:
                    mapping[c] = len(mapping)
                result.append(mapping[c])
            return result, count_colors(result)
        return colors, num_colors

    # Initial coloring with degree-ordered greedy
    best_colors = greedy_color(order_by_degree_desc())
    best_num = count_colors(best_colors)

    # Multi-pass iterated greedy
    max_iter = 40
    for iteration in range(max_iter):
        if best_num <= 1:
            break

        # Choose ordering strategy
        r = iteration % 4
        if r == 0:
            order = order_by_color_classes(best_colors, best_num)
        elif r == 1:
            order = order_by_degree_desc()
            random.shuffle(order[:min(n//4+1, n)])
        elif r == 2:
            order = order_by_saturation(best_colors)
        else:
            order = order_random()

        colors = greedy_color(order)
        num = count_colors(colors)

        if num < best_num:
            best_colors = colors
            best_num = num

        # Try to reduce by eliminating smallest class
        if iteration % 5 == 0:
            reduced, rnum = try_reduce_colors(best_colors, best_num)
            if rnum < best_num:
                best_colors = reduced
                best_num = rnum

    return best_colors

