def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []

    # Convert adjacency list to sets for O(1) lookup
    adj_sets = [set(neighbors) for neighbors in adj]

    # Stage 1: Greedy coloring with DSATUR-like ordering
    colors = [-1] * n
    saturation = [0] * n
    degree = [len(adj[i]) for i in range(n)]
    neighbor_colors = [set() for _ in range(n)]
    colored_count = 0

    # Use a simple greedy with largest-degree-first ordering
    order = sorted(range(n), key=lambda x: -degree[x])

    for u in order:
        # Find smallest color not used by neighbors
        used = neighbor_colors[u]
        c = 0
        while c in used:
            c += 1
        colors[u] = c
        # Update neighbor saturation
        for v in adj_sets[u]:
            if colors[v] == -1:
                neighbor_colors[v].add(c)

    # Stage 2: Eliminate rare colors by reassigning vertices
    # Find max color used
    max_color = max(colors)

    # Iteratively try to eliminate the highest color
    improved = True
    while improved and max_color > 0:
        improved = False
        # Find vertices with the highest color
        target_color = max_color
        candidates = [u for u in range(n) if colors[u] == target_color]

        if not candidates:
            max_color -= 1
            continue

        # Try to recolor each candidate to a lower color
        all_recolored = True
        for u in candidates:
            neighbor_cols = {colors[v] for v in adj_sets[u]}
            # Find smallest available color < target_color
            new_c = -1
            for c in range(target_color):
                if c not in neighbor_cols:
                    new_c = c
                    break
            if new_c == -1:
                all_recolored = False
                break
            colors[u] = new_c

        if all_recolored:
            max_color -= 1
            improved = True
        else:
            # Undo partial recoloring - restore candidates
            # Re-run greedy on candidates
            for u in candidates:
                neighbor_cols = {colors[v] for v in adj_sets[u]}
                c = 0
                while c in neighbor_cols:
                    c += 1
                colors[u] = c

    # Stage 3: Kempe chain swaps to reduce color count
    # Try a few passes of local improvement
    for _ in range(3):
        current_max = max(colors)
        if current_max == 0:
            break

        # Try to eliminate current_max by Kempe chain recoloring
        verts_with_max = [u for u in range(n) if colors[u] == current_max]

        for u in verts_with_max:
            if colors[u] != current_max:
                continue
            neighbor_cols = {colors[v] for v in adj_sets[u]}
            # Try each lower color
            for target in range(current_max):
                if target not in neighbor_cols:
                    colors[u] = target
                    break
            else:
                # Try Kempe chain: swap colors between two neighbor colors
                nc_list = list(neighbor_cols)
                swapped = False
                for i in range(len(nc_list)):
                    if swapped:
                        break
                    for j in range(i+1, len(nc_list)):
                        ca, cb = nc_list[i], nc_list[j]
                        if ca >= current_max or cb >= current_max:
                            continue
                        # Check if we can swap ca and cb in neighborhood of u
                        # Simple: just try swapping for neighbors of u with color ca or cb
                        affected = []
                        for v in adj_sets[u]:
                            if colors[v] == ca:
                                affected.append((v, ca, cb))
                            elif colors[v] == cb:
                                affected.append((v, cb, ca))
                        # Apply swap
                        for v, old_c, new_c in affected:
                            colors[v] = new_c
                        # Check validity
                        valid = True
                        for v, old_c, new_c in affected:
                            for w in adj_sets[v]:
                                if w != u and colors[w] == colors[v]:
                                    valid = False
                                    break
                        if valid and ca not in {colors[v] for v in adj_sets[u]}:
                            colors[u] = ca
                            swapped = True
                            break
                        else:
                            # Undo
                            for v, old_c, new_c in affected:
                                colors[v] = old_c

    return colors

