                       key=lambda v: (saturation[v], degree[v]))
            used = neighbor_colors[best]
            c = 0
            while c in used:
                c += 1
            colors[best] = c
            colored[best] = True
            for u in adj_sets[best]:
                if not colored[u] and c not in neighbor_colors[u]:
                    neighbor_colors[u].add(c)
                    saturation[u] += 1
        return colors

    def greedy_color(order):
        colors = [-1] * n
        for v in order:
            used = {colors[u] for u in adj_sets[v] if colors[u] >= 0}
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    def compact(colors):
        used = sorted(set(colors))
        remap = {old: new for new, old in enumerate(used)}
        return [remap[c] for c in colors]

    def try_reduce(colors):
        colors = colors[:]
        while True:
            max_c = max(colors)
            verts = [v for v in range(n) if colors[v] == max_c]
            changed = False
            for v in verts:
                nc = {colors[u] for u in adj_sets[v]}
                for c in range(max_c):
                    if c not in nc:
                        colors[v] = c
                        changed = True
                        break
            if not any(colors[v] == max_c for v in range(n)):
                colors = compact(colors)
                continue
            if not changed:
                break
        return colors

    def kempe_swap(colors, v, c1, c2):
        colors = colors[:]
        stack = [v]
        visited = {v}
        while stack:
            u = stack.pop()
            colors[u] = c2 if colors[u] == c1 else c1
            for w in adj_sets[u]:
                if w not in visited and colors[w] in (c1, c2):
                    visited.add(w)
                    stack.append(w)
        return colors

    def local_search(colors, iterations=400):
