                break
            v = random.choice(verts)
            nc_set = {colors[u] for u in adj_sets[v]}
            recolored = False
            for c in range(max_c):
                if c not in nc_set:
                    colors[v] = c
                    recolored = True
                    break
            if not recolored:
                for c in sorted(nc_set):
                    if c >= max_c:
                        continue
                    for u in adj_sets[v]:
                        if colors[u] == c:
                            new_c = kempe_swap(colors, u, c, max_c)
                            if c not in {new_c[w] for w in adj_sets[v]}:
                                new_c[v] = c
                                colors = new_c
                                recolored = True
                                break
                    if recolored:
                        break
            if not any(colors[v] == max_c for v in range(n)):
                colors = compact(colors)
            if max(colors) + 1 < best_nc:
                best_nc = max(colors) + 1
                best = colors[:]
        return best

    # DSATUR construction
    best = dsatur()
    best = try_reduce(best)
    best_nc = max(best) + 1

    # Try a few greedy orderings
    for _ in range(5):
        order = sorted(range(n), key=lambda v: (-degree[v], random.random()))
        c = greedy_color(order)
        c = try_reduce(c)
        if max(c) + 1 < best_nc:
            best = c
            best_nc = max(c) + 1

    # Local search on best found
    improved = local_search(best, iterations=500)
    if max(improved) + 1 < best_nc:
        best = improved
        best_nc = max(improved) + 1

    best = try_reduce(best)
    return best

