                        colors[v] = c
                        changed = True
                        break
            if not any(c == max_c for c in colors):
                colors = compact(colors)
                changed = True
        return colors

    def kempe_chain(colors, v, c1, c2):
        # Swap colors c1 and c2 in the component containing v
        new_colors = colors[:]
        stack = [v]
        visited = {v}
        while stack:
            u = stack.pop()
            new_colors[u] = c2 if new_colors[u] == c1 else c1
            for w in adj_sets[u]:
                if w not in visited and colors[w] in (c1, c2):
