                for c in candidates:
                    for u in adj_sets[v]:
                        if colors[u] == c:
                            new_c = kempe_chain(colors, u, c, max_c)
                            if c not in {new_c[w] for w in adj_sets[v]}:
                                new_c[v] = c
                                colors = new_c
                                recolored = True
