                    if recolored:
                        break
            # If vertex still has max color, try random neighbor recolor
            if not recolored and verts:
                u = random.choice(list(adj_sets[v])) if adj_sets[v] else v
                unc = {colors[w] for w in adj_sets[u] if w != v}
                for c in range(max_c + 1):
                    if c not in unc and c != colors[v]:
                        colors[u] = c
                        break
            if not any(c == max_c for c in colors):
                colors = compact(colors)
            nc = max(colors) + 1
            if nc < best_nc:
                best_nc = nc
                best = colors[:]
        return best

    # DSATUR construction
    best = dsatur()
    best = try_reduce(best)
    best_nc = max(best) + 1

    # Try greedy orderings with time budget
    for _ in range(3):
