            for w in adj_sets[u]:
                if w not in visited and colors[w] in (c1, c2):
                    visited.add(w)
                    stack.append(w)
        return colors

    def local_search(colors, iterations=600):
        colors = colors[:]
        best = colors[:]
        best_nc = max(colors) + 1
        for _ in range(iterations):
            max_c = max(colors)
            verts = [v for v in range(n) if colors[v] == max_c]
