                best = colors[:]
        return best

    def rlf_coloring():
        colors = [-1] * n
        uncolored = set(range(n))
        color_id = 0
        while uncolored:
            sub_deg = {v: sum(1 for nb in adj_sets[v] if nb in uncolored) for v in uncolored}
            # Start with highest degree vertex
            start = max(uncolored, key=lambda v: sub_deg[v])
            independent_set = []
            excluded = set()
            candidates = sorted(uncolored, key=lambda v: -sub_deg[v])
            # Use RLF: pick start, then prefer vertices with most neighbors in excluded
            independent_set.append(start)
            excluded.update(adj_sets[start])
            remaining = [v for v in candidates if v != start and v not in excluded]
            while remaining:
                # Pick vertex with most neighbors already excluded (most constrained by IS)
                v = max(remaining, key=lambda x: sum(1 for nb in adj_sets[x] if nb in excluded))
                independent_set.append(v)
                excluded.update(adj_sets[v])
                remaining = [u for u in remaining if u not in excluded and u != v]
            for v in independent_set:
                colors[v] = color_id
                uncolored.discard(v)
            color_id += 1
        return colors

    # Build multiple candidate solutions
    best = dsatur()
    best = try_reduce(best)
    best_nc = max(best) + 1

    # RLF coloring
    c = rlf_coloring()
    c = try_reduce(c)
    if max(c) + 1 < best_nc:
