        heapq.heapify(heap)
        in_heap = [True] * n
        sat = [0] * n
        for _ in range(n):
            while True:
                s, d, v = heapq.heappop(heap)
                if not colored[v] and sat[v] == -s:
                    break
            used = neighbor_colors[v]
