            for w in adj_sets[u]:
                if w not in visited and colors[w] in (c1, c2):
                    visited.add(w)
                    stack.append(w)
        return colors

    def local_search(colors, iterations=500):
        colors = colors[:]
        best = colors[:]
        best_nc = max(colors) + 1
        for _ in range(iterations):
            max_c = max(colors)
            verts = [v for v in range(n) if colors[v] == max_c]
            if not verts:
                break
            v = random.choice(verts)
            nc_set = {colors[u] for u in adj_sets[v]}
            recolored = False
            for c in range(max_c):
                if c not in nc_set:
                    colors[v] = c
                    recolored = True
                    break
            if not recolored:
                for c in sorted(nc_set):
                    if c >= max_c:
                        continue
                    for u in adj_sets[v]:
                        if colors[u] == c:
                            new_c = kempe_swap(colors, u, c, max_c)
                            if c not in {new_c[w] for w in adj_sets[v]}:
