                excluded.update(adj_sets[v] & uncolored)
                remaining -= adj_sets[v]
                remaining.discard(v)
            for v in independent_set:
                colors[v] = color_id
                uncolored.discard(v)
            color_id += 1
        return colors

    # Build best solution from multiple strategies
    best = dsatur()
    best = try_reduce(best)
    best_nc = max(best) + 1

    # RLF coloring
    c = rlf_coloring()
    c = try_reduce(c)
    if max(c) + 1 < best_nc:
        best = c
        best_nc = max(best) + 1

    # Greedy with random orderings
    for _ in range(3):
        order = sorted(range(n), key=lambda v: (-degree[v], random.random()))
        c = greedy_color(order)
        c = try_reduce(c)
        if max(c) + 1 < best_nc:
            best = c
            best_nc = max(best) + 1

    # Local search on best
    improved = local_search(best, iterations=600)
    improved = try_reduce(improved)
    if max(improved) + 1 < best_nc:
        best = improved

    return best

