        return max(colors) + 1

    def dsatur():
        colors = [-1] * n
        sat = [0] * n
        deg = [len(adj_sets[v]) for v in range(n)]
        done = [False] * n
        nc = [set() for _ in range(n)]
        for _ in range(n):
            best = max((v for v in range(n) if not done[v]),
                       key=lambda v: (sat[v], deg[v]))
            used = nc[best]
            c = 0
            while c in used:
                c += 1
            colors[best] = c
            done[best] = True
            for u in adj_sets[best]:
                if not done[u] and c not in nc[u]:
                    nc[u].add(c)
                    sat[u] += 1
        return colors

    def get_classes(colors, k):
        cls = [[] for _ in range(k)]
        for v, c in enumerate(colors):
            cls[c].append(v)
        return cls

    def try_reduce(colors, k):
        # Try to eliminate color k-1 (smallest class) by recoloring its vertices
        cls = get_classes(colors, k)
        cls.sort(key=len)
        target_class = cls[0]
        new_colors = colors[:]
        for v in target_class:
            new_colors[v] = -1
        # Try to recolor each vertex in target class with existing colors
        for v in target_class:
            used = {new_colors[u] for u in adj_sets[v] if new_colors[u] >= 0}
            available = [c for c in range(k - 1) if c not in used]
            if available:
                new_colors[v] = available[0]
            else:
                return None  # Can't reduce
        return new_colors

    def iterated_greedy(init_colors, time_budget=40):
        best = init_colors[:]
        best_k = num_colors(best)

        for _ in range(time_budget):
            k = num_colors(best)
            cls = get_classes(best, k)
            cls.sort(key=lambda c: -len(c))

            # Try multiple orderings
            for shuffle in range(3):
                order = []
                for c in cls:
                    if shuffle == 0:
                        order.extend(c)
                    elif shuffle == 1:
                        tmp = c[:]
                        random.shuffle(tmp)
                        order.extend(tmp)
                    else:
                        order.extend(reversed(c))

                nc = greedy_color(order)
                nk = num_colors(nc)
                if nk < best_k:
                    best = nc
                    best_k = nk

        return best

    # Initial coloring
    best_colors = dsatur()
    best_k = num_colors(best_colors)

    # Iterated greedy improvement
    best_colors = iterated_greedy(best_colors, time_budget=30)
    best_k = num_colors(best_colors)

    # Try to reduce color count by eliminating smallest class
    for _ in range(best_k):
        reduced = try_reduce(best_colors, best_k)
